import pathlib,stat,hashlib,os,re
def restore_objects(store,backup,manifest):
    store=pathlib.Path(store);backup=pathlib.Path(backup)
    if not isinstance(manifest,dict) or not 1<=len(manifest)<=8:raise ValueError('bounded approved inventory')
    def safe(root,key):
        if not isinstance(key,str) or not key.startswith('fake/') or pathlib.PurePosixPath(key).is_absolute() or str(pathlib.PurePosixPath(key))!=key or any(v in ('.','..') for v in pathlib.PurePosixPath(key).parts):raise ValueError('approved chunk paths only')
        current=root
        for part in [None,*pathlib.PurePosixPath(key).parts[:-1]]:
            if part is not None:current=current/part
            info=current.lstat()
            if not stat.S_ISDIR(info.st_mode) or info.st_uid!=os.geteuid():raise ValueError('owned nonsymlink directory')
        return root/key
    plans=[]
    try:
        for key,expected in sorted(manifest.items()):
            if not isinstance(expected,str) or not re.fullmatch('[0-9a-f]{64}',expected):raise ValueError('approved SHA256')
            source=safe(backup,key);target=safe(store,key);info=source.lstat()
            if not stat.S_ISREG(info.st_mode) or info.st_uid!=os.geteuid() or info.st_size>1024*1024:raise ValueError('bounded regular backup object')
            payload=source.read_bytes()
            if hashlib.sha256(payload).hexdigest()!=expected:raise ValueError('backup checksum mismatch')
            if os.path.lexists(target):
                info=target.lstat()
                if not stat.S_ISREG(info.st_mode) or info.st_uid!=os.geteuid():raise ValueError('existing object identity')
                if hashlib.sha256(target.read_bytes()).hexdigest()!=expected:raise ValueError('existing object conflict')
            else:plans.append((key,target,payload))
    except OSError as error:raise ValueError('approved restore source/path unavailable') from error
    restored=[]
    for key,target,payload in plans:
        fd=os.open(target,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600);identity=os.fstat(fd)
        try:
            with os.fdopen(fd,'wb') as out:out.write(payload);out.flush();os.fsync(out.fileno())
            folder=os.open(target.parent,os.O_RDONLY|os.O_DIRECTORY)
            try:os.fsync(folder)
            finally:os.close(folder)
            restored.append(key)
        except BaseException:
            if target.exists() and (target.stat().st_dev,target.stat().st_ino)==(identity.st_dev,identity.st_ino):target.unlink()
            raise
    return restored
